import pandas as pd
from collections import defaultdict

log_data = [{'timestamp': '2025-05-13T21:00:03', 'host': '192.168.1.10', 'program': 'sshd', 'message': 'Accepted password for user1 from 192.168.1.10 port 22 ssh2', 'severity': 'info', 'category': 'auth'}, {'timestamp': '2025-05-13T21:00:05', 'host': '192.168.1.11', 'program': 'sshd', 'message': 'Failed password for invalid user user2 from 192.168.1.11 port 22 ssh2', 'severity': 'warning', 'category': 'auth'}, {'timestamp': '2025-05-13T21:00:07', 'host': '192.168.1.10', 'program': 'sshd', 'message': 'Accepted password for user1 from 192.168.1.10 port 22 ssh2', 'severity': 'info', 'category': 'auth'}, {'timestamp': '2025-05-13T21:00:08', 'host': '192.168.1.11', 'program': 'sshd', 'message': 'Accepted password for user2 from 192.168.1.11 port 22 ssh2', 'severity': 'info', 'category': 'auth'}]

login_attempts = defaultdict(lambda: {'success': 0, 'failed': 0})

for log in log_data:
    host = log['host']
    if 'Failed password' in log['message']:
        login_attempts[host]['failed'] += 1
    elif 'Accepted password' in log['message']:
        login_attempts[host]['success'] += 1

# Output Summary
for host, attempts in login_attempts.items():
    print(f'Host: {host}, Successful Attempts: {attempts['success']}, Failed Attempts: {attempts['failed']}')

severity_counts = {'info': 4, 'error': 1, 'warning': 1}

for entry in log_data:
    severity = entry['severity']
    if severity in severity_counts:
        severity_counts[severity] += 1
    else:
        severity_counts[severity] = 1

# Print the results
print(severity_counts)

unique_ips = set() 
for entry in log_data: 
    if 'from' in entry['message']: 
        ip_address = entry['message'].split('from ')[1].split(' ')[0] 
        unique_ips.add(ip_address) 
